fn solve(n: i8) -> i8 {
    if n % 2 != 0 {
        // If n is odd
        (n - 1) / 2
    } else {
        // If n is even, find the largest power of two less than or equal to n
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

fn largest_power_of_two_le(n: i8) -> i8 {
    let mut power = 1;
    while power <= n {
        power <<= 1; // Multiply power by 2
    }
    power >> 1 // Return the largest power of two less than or equal to n
}

